import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Main {

    // use an auxiliary class to mimic static fields but enclosed
    static class Solver {
        char[] chars;
        int answer = 0;
        int xDigit = 0;

        void search(int pos, int val) {
            int n = chars.length;
            if (pos >= n) {
                if (val % 25 == 0) answer++;
                return;
            }
            int digit = chars[pos] - '0';
            if (digit >= 0 && digit <= 9) {
                search(pos + 1, val * 10 + digit);
            } else if (chars[pos] == 'X') {
                search(pos + 1, val * 10 + xDigit);
            } else { // '_'
                if (pos == n - 1) {
                    search(pos + 1, val * 10 + 5);
                    search(pos + 1, val * 10);
                } else {
                    int start = (pos == 0) ? 1 : 0;
                    for (int i = start; i < 10; i++) {
                        search(pos + 1, val * 10 + i);
                    }
                }
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        br.close();
        if (line == null) {
            System.out.println(0);
            return;
        }
        // ignore trailing newline, first token only
        String token = line.split("\\s+")[0];
        char[] cs = token.toCharArray();
        int n = cs.length;
        if (cs[0] == '0' && n != 1) {
            System.out.println(0);
            return;
        }
        boolean hasX = false;
        for (char c : cs) {
            if (c == 'X') {
                hasX = true;
                break;
            }
        }
        Solver solver = new Solver();
        solver.chars = cs;
        if (hasX) {
            for (int v = 0; v < 10; v++) {
                if (cs[0] == 'X' && n > 1 && v == 0) continue;
                solver.xDigit = v;
                solver.search(0, 0);
            }
        } else {
            solver.search(0, 0);
        }
        System.out.println(solver.answer);
    }
}
